ME, RIVAL = 1, 2
MINE, THEIRS = 11, 22  # entrant ids
_CHARS = {
    "mac": Character(id=1, name="Little Mac", char_group="little_mac", char_icon="char_icons/little_mac.png"),
    "cloud": Character(id=2, name="Cloud", char_group="cloud"),
    "steve": Character(id=3, name="Steve", char_group="steve"),
    "pt": Character(id=4, name="Pokemon Trainer", char_group="pokemon_trainer"),
}
LOOKUP = PlayerLookup(query="Mac", match_type="tag_exact", player_id=ME, tag="Mac")


def _game(number: int, mine: str | None, theirs: str | None, stage: str | None = None, *, won: bool | None) -> Game:
    picks = [(MINE, mine), (THEIRS, theirs)]
    return Game(
        number=number,
        winner_entrant_id=None if won is None else MINE if won else THEIRS,
        stage=Stage(id=1, name=stage) if stage else None,
        selections=[Selection(entrant_id=e, character=_CHARS[c]) for e, c in picks if c],
    )


def _set(day: int, games: list[Game], event: int = 1, *, won: bool = True, vod: str | None = None) -> Set:
    """A set on November `day`, 2026 at event `event`"""
    return Set(
        id=f"s{day}-{event}",
        completed_at=dt.datetime(2026, 11, day, tzinfo=dt.UTC),
        round_text="Winners Final",
        winner_entrant_id=MINE if won else THEIRS,
        vod_url=vod,
        event=Event(
            id=event,
            name="Singles",
            slug=f"tournament/weekly-{event}/event/singles",
            online=False,
            tournament=Tournament(id=event, name=f"Weekly {event}", slug=f"tournament/weekly-{event}"),
        ),
        sides=[
            SetSide(entrant_id=MINE, players=[Player(id=ME, tag="Mac")], seed=1, score=2 if won else 0, placement=1),
            SetSide(entrant_id=THEIRS, players=[Player(id=RIVAL, tag="Rival")], seed=5, score=0 if won else 2),
        ],
        games=games,
    )


def _sets() -> list[Set]:
    """Three sets, newest first, with every situation the usage maths separates"""
    return [
        # opens Mac on PS2 and loses; comes back as Cloud on their own pick (BF) and wins;
        # stays Cloud on the opponent's pick (FD)
        _set(
            10,
            [
                _game(1, "mac", "steve", "Pokémon Stadium 2", won=False),
                _game(2, "cloud", "steve", "Battlefield", won=True),
                _game(3, "cloud", "steve", "Final Destination", won=True),
            ],
            event=2,
        ),
        # only a set score was reported
        _set(9, [], event=2),
        # no stages; switches after a game they won; game 3 has no character for them
        _set(
            3,
            [_game(1, "mac", "pt", won=True), _game(2, "cloud", "pt", won=False), _game(3, None, "pt", won=True)],
            event=1,
            won=True,
        ),
    ]


def _names(stats) -> list[tuple[str, int]]:
    return [(c.character, c.count) for c in stats.characters]


def test_recent_and_game_1_characters():
    got = usage.usage_from_sets(_sets(), LOOKUP)
    assert _names(got.recent) == [("Cloud", 3), ("Little Mac", 2)]
    assert (got.recent.unit, got.recent.total) == ("games", 5)
    assert got.recent.characters[0].usage_pct == pytest.approx(60.0)
    assert (got.recent.characters[1].char_group, got.recent.characters[1].char_icon) == (
        "little_mac",
        "char_icons/little_mac.png",
    )
    assert _names(got.game_1) == [("Little Mac", 2)]


def test_window_reports_what_was_counted():
    got = usage.usage_from_sets(_sets(), LOOKUP, requests=2)
    window = got.window
    assert (window.sets, window.games, window.requests) == (3, 5, 2)
    assert window.events == len({s.event.id for s in _sets()})
    assert (window.first_date, window.last_date) == (dt.date(2026, 11, 3), dt.date(2026, 11, 10))


def test_stages_by_who_picked():
    got = usage.usage_from_sets(_sets(), LOOKUP)
    assert [(s.stage, s.games) for s in got.starters.stages] == [("Pokémon Stadium 2", 1)]
    assert [(s.stage, s.games) for s in got.counterpicks.stages] == [("Battlefield", 1)]  # after their loss
    assert [(s.stage, s.games) for s in got.taken_to.stages] == [("Final Destination", 1)]  # after their win
    assert got.starters.stages[0].usage_pct == pytest.approx(100.0)
    # no stage reported anywhere: empty stats, not an error
    bare = usage.usage_from_sets([_sets()[2]], LOOKUP)
    assert (bare.starters.games, bare.starters.stages, bare.counterpicks.games) == (0, [], 0)


def test_switches_within_a_set():
    switches = usage.usage_from_sets(_sets(), LOOKUP).switches
    assert (switches.sets, switches.sets_with_switch) == (2, 2)
    # set 10: game 2 follows a loss (Mac -> Cloud: switched), game 3 follows a win (stayed)
    # set 3: game 2 follows a win (Mac -> Cloud: switched); game 3 has no character
    assert (switches.chances_after_losing, switches.switched_after_losing) == (1, 1)
    assert (switches.chances_after_winning, switches.switched_after_winning) == (2, 1)


def test_last_events_count_per_event():
    got = usage.usage_from_sets(_sets(), LOOKUP).last_events
    assert [(e.tournament, e.date) for e in got.events] == [
        ("Weekly 2", dt.date(2026, 11, 10)),
        ("Weekly 1", dt.date(2026, 11, 3)),
    ]
    assert [(c.character, c.games) for c in got.events[0].characters] == [("Cloud", 2), ("Little Mac", 1)]
    assert got.events[0].url == "https://www.start.gg/tournament/weekly-2/event/singles"
    assert (got.characters.unit, got.characters.total) == ("events", 2)
    assert dict(_names(got.characters)) == {"Cloud": 2, "Little Mac": 2}
    assert (got.first_date, got.last_date) == (dt.date(2026, 11, 3), dt.date(2026, 11, 10))
    only_newest = usage.usage_from_sets(_sets(), LOOKUP, events=1).last_events
    assert [e.tournament for e in only_newest.events] == ["Weekly 2"]
    # an event with only set scores is listed with no characters and doesn't count as data
    scores_only = usage.usage_from_sets([_sets()[1]], LOOKUP).last_events
    assert (scores_only.events[0].characters, scores_only.characters.total) == ([], 0)


def test_vs_characters_narrow_every_count():
    got = usage.usage_from_sets(_sets(), LOOKUP, vs_characters=[CharGroup.STEVE])
    assert got.vs_characters == ["steve"]
    assert (got.window.sets, got.window.games) == (1, 3)
    assert _names(got.recent) == [("Cloud", 2), ("Little Mac", 1)]
    assert [e.tournament for e in got.last_events.events] == ["Weekly 2"]
    assert got.switches.sets == 1
    assert usage.usage_from_sets(_sets(), LOOKUP, vs_characters=[CharGroup.FOX]).window.games == 0
    # several: games against any of them
    both = usage.usage_from_sets(_sets(), LOOKUP, vs_characters=[CharGroup.STEVE, CharGroup.POKEMON_TRAINER])
    assert (both.window.sets, both.window.games) == (2, 5)


@pytest.mark.parametrize("given", ["pokemon_trainer", "pt_squirtle", "pt_ivysaur", "Charizard", "Pokemon Trainer"])
def test_vs_characters_accept_a_group_or_any_member(given):
    got = usage.usage_from_sets(_sets(), LOOKUP, vs_characters=[usage.vs_char_group(given)])
    assert (got.vs_characters, got.window.sets, got.window.games) == (["pokemon_trainer"], 1, 2)


def test_vs_char_group():
    assert usage.vs_char_group("Little Mac") == "little_mac"
    assert usage.vs_char_group("steve") == "steve"
    assert usage.vs_char_group("Pokemon Trainer") == "pokemon_trainer"
    assert usage.vs_char_group("mythra") is CharGroup.PYRA_MYTHRA
    assert usage.vs_char_group(CharGroup.CLOUD) is CharGroup.CLOUD
    with pytest.raises(ValueError, match="unknown character"):
        usage.vs_char_group("Goku")


_RESULT_WORDS = {"winner", "won", "wins", "lost", "losses", "score", "placement", "seed", "rank", "record", "dq"}


def _field_names(schema: dict) -> set[str]:
    names = set()
    for definition in [schema, *schema.get("$defs", {}).values()]:
        names |= set(definition.get("properties", {}))
    return names


def test_player_usage_carries_no_results():
    """Usage is facts only: no field name says who won, a score, a seed or a placement.

    (`switched_after_losing` and friends are pick habits; they are built from `after_`, never
    a bare result word.)
    """
    names = _field_names(derived.PlayerUsage.model_json_schema())
    leaked = {name for name in names if _RESULT_WORDS & set(name.split("_"))}
    assert not leaked
    dumped = usage.usage_from_sets(_sets(), LOOKUP).model_dump_json()
    assert "Rival" not in dumped  # nor who they played


