@pytest.fixture
def fetched(monkeypatch):
    """resolve_player and player_sets answer from canned sets; records the fetch arguments"""
    seen = {}

    async def resolve(player):
        return (
            LOOKUP
            if player == "Mac"
            else PlayerLookup(query=player, match_type="tag_exact", player_id=RIVAL, tag=player)
        )

    async def player_sets(player_id, **kwargs):
        seen.update(kwargs, player_id=player_id)
        return [
            _set(10, [_game(1, "mac", "steve", "Battlefield", won=True)], vod="https://youtu.be/x"),
            _set(3, [], won=False),
        ]

    for module in (derived.matchups, results, usage):
        monkeypatch.setattr(module, "resolve_player", resolve)
    monkeypatch.setattr(startgg, "player_sets", player_sets)
    return seen


def test_head_to_head_keeps_results(fetched):
    h2h = asyncio.run(derived.head_to_head("Mac", "Rival", max_sets=2))
    assert (fetched["player_id"], fetched["opponent_id"], fetched["max_sets"]) == (ME, RIVAL, 2)
    assert (h2h.player_1.tag, h2h.player_2.tag) == ("Mac", "Rival")
    assert (h2h.sets_won_1, h2h.sets_won_2, h2h.capped) == (1, 1, True)
    newest = h2h.sets[0]
    assert (newest.winner, newest.score_1, newest.score_2, newest.seed_1, newest.seed_2) == (1, 2, 0, 1, 5)
    assert (newest.tournament, newest.round, newest.vod_url) == ("Weekly 1", "Winners Final", "https://youtu.be/x")
    game = newest.games[0]
    assert (game.char_group_1, game.character_2, game.stage, game.winner) == ("little_mac", "Steve", "Battlefield", 1)
    assert h2h.sets[1].games == []


def test_player_results(fetched):
    got = asyncio.run(results.player_results("Mac", months=2, max_sets=50))
    assert (got.sets_won, got.sets_lost, got.capped) == (1, 1, False)
    assert (got.first_date, got.last_date) == (dt.date(2026, 11, 3), dt.date(2026, 11, 10))
    first = got.sets[0]
    assert (first.opponent, first.opponent_id, first.won, first.dq) == ("Rival", RIVAL, True, False)
    assert fetched["since"] < dt.datetime.now(dt.UTC) - dt.timedelta(days=59)


def test_player_usage_reads_one_request_of_the_newest_sets(fetched):
    got = asyncio.run(derived.player_usage("Mac", vs_characters=["Steve", "steve", "Pac-Man"]))
    per_page = startgg.USAGE_PER_PAGE
    assert (fetched["max_pages"], fetched["per_page"], fetched["max_sets"]) == (1, per_page, per_page)
    assert fetched["query"] is startgg.queries.USAGE_SETS
    assert fetched["characters"] is not None  # stored (startgg_char.parquet): no request for them
    assert "since" not in fetched or fetched["since"] is None
    assert (got.window.requests, got.vs_characters) == (1, ["steve", "pac_man"])  # once each, in order
    assert asyncio.run(derived.player_usage("Mac", requests=2)).window.requests == 2
    assert fetched["max_pages"] == 2
    assert (fetched["online"], got.setting) == (None, "all")
    offline = asyncio.run(derived.player_usage("Mac", setting="offline"))
    assert (fetched["online"], offline.setting) == (False, "offline")
    assert asyncio.run(derived.player_usage("Mac", setting="online")).setting == "online"
    assert fetched["online"] is True
    with pytest.raises(ValueError, match="setting must be one of"):
        asyncio.run(derived.player_usage("Mac", setting="lan"))
    assert _names(got.recent) == [("Little Mac", 1)]
    with pytest.raises(ValueError, match="unknown character"):
        asyncio.run(derived.player_usage("Mac", vs_characters=["Goku"]))
